export function changeTaskExecutionPolicy({state,taskId,policy,identity,mode,checkpointPermissions=[]}={}){const b=policyBinding(state,taskId);if(!b)return {ok:false,reason:'current_task_required'};if(identity?.kind!=='human'||identity.subject!==state.meta.ownerId)return {ok:false,reason:'site_owner_required'};try{if(controlPrincipal(state,identity).role!=='human')return {ok:false,reason:'site_owner_required'};}catch{return {ok:false,reason:'site_owner_required'};}if(!['manual','agentic'].includes(mode))return {ok:false,reason:'invalid_mode'};if(!Array.isArray(checkpointPermissions)||checkpointPermissions.some(x=>!policyCheckpoints.includes(x)))return {ok:false,reason:'checkpoint_not_permitted'};if(mode==='agentic'&&(!b.scopeId||!Number.isSafeInteger(b.scopeRevision)))return {ok:false,reason:'current_scope_required'};const previous=policy||defaultExecutionPolicy({state,taskId});if(previous.taskId!==taskId||!Number.isSafeInteger(previous.executionPolicyRevision)||!Number.isSafeInteger(previous.ownerGrantRevision)||!Array.isArray(previous.checkpoints))return {ok:false,reason:'policy_binding_mismatch'};const checkpoints=mode==='agentic'?[...new Set(checkpointPermissions)]:[];const grantChanged=previous.siteOwnerId!==b.siteOwnerId||previous.epoch!==b.epoch||previous.projectOwner!==b.projectOwner||previous.projectFence!==b.projectFence||previous.scopeId!==b.scopeId||previous.scopeRevision!==b.scopeRevision||previous.checkpoints.length!==checkpoints.length||previous.checkpoints.some(x=>!checkpoints.includes(x));return {ok:true,policy:{id:b.taskId,taskId:b.taskId,mode,executionPolicyRevision:previous.executionPolicyRevision+1,ownerGrantRevision:previous.ownerGrantRevision+(grantChanged?1:0),checkpoints,epoch:b.epoch,scopeId:b.scopeId,scopeRevision:b.scopeRevision,siteOwnerId:b.siteOwnerId,projectOwner:b.projectOwner,projectFence:b.projectFence}};}
