const currentPlanDecision=(s,t)=>{const d=t.agenticPlanDecision,p=policyFor(s,t);return !!d&&p.mode==='agentic'&&p.checkpoints.includes('plan_review')&&d.provenance==='execution-policy'&&d.checkpoint==='plan_review'&&d.epoch===s.meta.epoch&&d.siteOwnerId===s.meta.ownerId&&d.ownerGrantRevision===p.ownerGrantRevision&&d.executionPolicyRevision===p.executionPolicyRevision&&d.scopeRevision===t.scopeRevision&&d.scopeId===scope(t)&&d.planRevision===t.planRevision&&!!t.plan&&taskAuthority(s,t)?.owner===d.projectOwner&&taskAuthority(s,t)?.ownershipFence===d.projectFence&&d.agentFence===(entity(s,'agents',d.decidingAgent)?.executionFence||0)&&p.projectOwner===d.projectOwner&&p.projectFence===d.projectFence;};
const currentFinalDecision=(s,t)=>{const d=t.agenticFinalDecision,p=policyFor(s,t);return !!d&&p.mode==='agentic'&&p.checkpoints.includes('human_review')&&d.provenance==='execution-policy'&&d.checkpoint==='human_review'&&d.epoch===s.meta.epoch&&d.siteOwnerId===s.meta.ownerId&&d.ownerGrantRevision===p.ownerGrantRevision&&d.executionPolicyRevision===p.executionPolicyRevision&&d.scopeRevision===t.scopeRevision&&d.scopeId===scope(t)&&d.planRevision===t.planRevision&&!!t.plan&&d.buildRevision===t.buildRevision&&d.evidenceRevision===t.evidence?.revision&&matches(t.evidence,t,true)&&taskAuthority(s,t)?.owner===d.projectOwner&&taskAuthority(s,t)?.ownershipFence===d.projectFence&&d.agentFence===(entity(s,'agents',d.decidingAgent)?.executionFence||0)&&p.projectOwner===d.projectOwner&&p.projectFence===d.projectFence;};
const planEligible=(s,t)=>matches(t.planApproval,t)||currentPlanDecision(s,t);
