function lease(s,t,p,c,now){projectWrite(s,p,t.projectId,c);check(live(s,t,now)&&t.lease.actor===p.actor,'LEASE_REQUIRED','Claim the task and renew its execution lease.');check(c.fence===t.fence,'STALE_FENCE','Task lease changed. Stop and refresh.');}
function dependencies(s,t){return t.dependencies.map(id=>entity(s,'tasks',id));}
function dependenciesReady(s,t){check(dependencies(s,t).every(x=>x?.stage==='ready'&&!x.blocker&&finalEligible(s,x)),'DEPENDENCIES_PENDING','Dependencies need final approval.');}
function validatedDependencies(s,value,id){check(Array.isArray(value)&&value.length<=30&&value.every(x=>typeof x==='string'&&x!==id&&entity(s,'tasks',x)),'INVALID_DEPENDENCIES','Select existing tasks other than this task.',400);const visit=(node,seen=new Set())=>{check(node!==id,'DEPENDENCY_CYCLE','This dependency creates a cycle.',400);if(seen.has(node))return;seen.add(node);for(const child of entity(s,'tasks',node).dependencies)visit(child,seen);};value.forEach(x=>visit(x));return [...new Set(value)];}
function taskInput(s,input,existing){check(input&&typeof input==='object','INVALID_INPUT','Task details required.',400);const value={title:str(input.title,'Title',160,3),description:str(input.description||'','Description',12000,0),component:str(input.component||'general','Component',180),environment:str(input.environment||'Development','Environment',120),priority:input.priority||'Normal',projectId:input.projectId||'relay',type:input.type||'Task'};check(['Urgent','High','Normal','Low'].includes(value.priority)&&['Feature','Bug','Task','Question'].includes(value.type),'INVALID_INPUT','Invalid priority or type.',400);check(entity(s,'projects',value.projectId),'PROJECT_NOT_FOUND','Select a project.',400);value.dependencies=validatedDependencies(s,input.dependencies||[],existing?.id);
  value.featureId=input.featureId||null;value.featureGroup=str(input.featureGroup||'','Feature group',80,0);value.layer=str(input.layer||'','Layer',80,0);
  if(value.featureId){const feature=entity(s,'tasks',value.featureId);check(feature&&feature.id!==existing?.id&&feature.type==='Feature'&&!feature.featureId&&feature.projectId===value.projectId&&value.type!=='Feature','INVALID_FEATURE','Select a feature in this project. Features cannot be nested.',400);}
  if(existing&&s.tasks.some(t=>t.featureId===existing.id))check(value.type==='Feature'&&value.projectId===existing.projectId,'FEATURE_HAS_TASKS','Move attached tasks before changing the feature type or project.');
  return value;}
function wake(s,recipient,reason,target,now,cause){if(!CONTROL_AGENTS[recipient])return;const id=`${cause}:${recipient}`;if(entity(s,'wakes',id))return;const project=target.projectId?entity(s,'projects',target.projectId):null;s.wakes.push({id,recipient,reason,target,projectFence:project?.ownershipFence??null,status:'pending',attempts:0,nextAt:now,at:iso(now),acknowledgedAt:null,slackId:crypto.randomUUID()});}
function wakeProject(s,id,reason,target,now,cause){const task=target.taskId?entity(s,'tasks',target.taskId):null;if(task?.team){const recipients=teamRecipients(s,task,now,{invite:['task-created','task-assigned'].includes(reason)});for(const recipient of recipients){const key=cause+':'+task.id+':'+task.team.fence;wake(s,recipient,reason,{...target,projectId:id},now,key);const item=entity(s,'wakes',key+':'+recipient);if(item){item.optionalPlanning=!!task.team.owner&&recipient!==task.team.owner;item.teamFence=task.team.fence;item.teamRound=task.team.round;item.teamPlanRevision=task.planRevision;}}return;}const project=entity(s,'projects',id);if(!project||project.recoveryRequired)return;const recipients=project.owner?[project.owner]:s.agents.filter(a=>!a.paused).map(a=>a.id);for(const recipient of recipients)wake(s,recipient,reason,{...target,projectId:id},now,cause);}
export function currentWake(s,w){if(w.status==='cancelled'||w.target?.taskId&&entity(s,'tasks',w.target.taskId)?.archivedAt)return false;const teamTask=w.target?.taskId?entity(s,'tasks',w.target.taskId):null;if(w.teamFence!==undefined){return !!teamTask?.team&&teamTask.stage!=='ready'&&teamTask.team.fence===w.teamFence&&teamTask.team.round===w.teamRound&&(!teamTask.team.owner||teamTask.team.owner===w.recipient||w.optionalPlanning&&teamTask.team.phase==='planning'&&['intake','research'].includes(teamTask.stage)&&planningAvailable(s,w.recipient,Date.parse(w.at)))&&entity(s,'projects',teamTask.projectId)?.status==='active';}const id=w.target?.projectId||(w.target?.taskId?entity(s,'tasks',w.target.taskId)?.projectId:null);if(id){const p=entity(s,'projects',id);if(!p||p.recoveryRequired||p.ownershipFence!==w.projectFence||(p.owner&&p.owner!==w.recipient))return false;}if(w.target?.jobId){const j=entity(s,'jobs',w.target.jobId);if(!j||j.status==='complete'||j.type==='conversation'||(j.owner&&j.owner!==w.recipient))return false;}return true;}
function cancelWakes(s,id){ /* Assignment fences invalidate pending delivery without rewriting the outbox. */ }
function refreshRecipients(s,project){ /* Project recipients and stale execution are derived from current assignment. */ }
function setOwner(s,project,target,p,reason,now,cause){const from=project.owner;project.owner=target;project.ownershipFence++;project.version++;project.recoveryRequired=false;project.assignedAt=target?iso(now):null;event(s,p,'project_assignment',`${from||'Unassigned'} → ${target||'Unassigned'}: ${reason}`,now,null,{projectId:project.id,previousOwner:from,owner:target,ownershipFence:project.ownershipFence});wakeProject(s,project.id,'project-assigned',{},now,cause);}
function takeLease(s,t,p,c,now){only(p,['agent']);let project=projectWrite(s,p,t.projectId,c);check(!t.blocker,'TASK_BLOCKED','Resolve the blocker first.');check(['intake','research','build'].includes(t.stage),'INVALID_STAGE','Task is waiting for review or is complete.');check(!live(s,t,now),'ALREADY_CLAIMED','Task already has an execution lease. Renew it or release it.');check(!s.tasks.some(x=>x.id!==t.id&&scope(x)===scope(t)&&live(s,x,now)),'SCOPE_CONFLICT','Another task holds this component and environment.');if(t.stage==='build'){check(planEligible(s,t),'PLAN_APPROVAL_REQUIRED','Current plan needs human approval or a valid current policy decision.');dependenciesReady(s,t);}if(t.team&&!t.team.owner){claimTeamTask(s,t,p.actor,now);project=taskAuthority(s,t);const policy=entity(s,'executionPolicies',t.id);if(policy&&policy.projectOwner===null&&policy.scopeRevision===t.scopeRevision){policy.projectOwner=project.owner;policy.projectFence=project.ownershipFence;policy.executionPolicyRevision++;}wakeProject(s,t.projectId,'task-assigned',{taskId:t.id},now,'claim:'+s.meta.revision+':'+t.id);}if(t.stage==='intake')t.stage='research';t.owner=project.owner;t.fence++;t.lease={until:now+900000,projectFence:project.ownershipFence,actor:p.actor,agentFence:entity(s,'agents',p.actor).executionFence||0};return t.fence;}
function newTask(s,input,p,now,teamPlanning=false){check(input?.executionMode===undefined||['work','agentic'].includes(input.executionMode),'INVALID_MODE','Choose Work or Agentic mode.',400);check(input?.executionMode!=='agentic'||p.role==='human','FORBIDDEN','Only a human may enable Agentic mode.',403);const fields=taskInput(s,input),project=entity(s,'projects',fields.projectId);check(project.status==='active','PROJECT_COMPLETED','Reopen the project first.');const t={id:`RLY-${crypto.randomUUID().slice(0,8).toUpperCase()}`,...fields,stage:'intake',version:1,scopeRevision:1,planRevision:0,buildRevision:0,plan:null,planApproval:null,agenticPlanDecision:null,evidence:null,review:null,finalApproval:null,agenticFinalDecision:null,owner:project.owner,builder:null,fence:0,lease:null,blocker:null,readReceipts:[],createdAt:iso(now),updatedAt:iso(now),synthetic:false};if(teamPlanning)startTeamPlanning(t);s.tasks.push(t);event(s,p,'task_created','Task created.',now,t);return t;}
function requestTaskStart(s,t,p,now,cause){const project=taskAuthority(s,t);check(project?.status==='active','PROJECT_COMPLETED','Reopen the project before starting work.');check(project.owner&&!project.recoveryRequired,'PROJECT_UNASSIGNED','Assign a project owner before starting this task.');check(['intake','research','build'].includes(t.stage),'INVALID_STAGE','Task is waiting for approval or is complete.');check(!t.blocker,'TASK_BLOCKED','Resolve the blocker before starting work.');const receipt=event(s,p,'task_start_requested','Task start requested from project owner.',now,t);wakeProject(s,t.projectId,'task-start-requested',{taskId:t.id,startRequestId:receipt.id},now,cause);return receipt.id;}
function newProject(id,name,description,now){return {id,name,description,owner:null,ownershipFence:0,ownershipVersion:1,recoveryRequired:false,status:'active',version:1,createdAt:iso(now)};}
export function initialControl(ownerId,legacy,now){const s=Object.fromEntries(kinds.map(kind=>[kind,[]]));s.meta={ownerId,epoch:crypto.randomUUID(),revision:1,createdAt:now};s.projects.push(newProject('relay','Relay','Agent task management and project planning',now));for(const [id,name]of Object.entries(CONTROL_AGENTS).filter(([id])=>id!=='lens'))s.agents.push({id,name,paused:false,lastHeartbeat:null,currentAction:null});s.settings.push({id:'integrations',slackEnabled:false,channel:'',mentions:{}});const human={actor:'human',role:'human'};for(const old of legacy?.state?.tasks||[]){const t=newTask(s,{...old,dependencies:[],projectId:'relay'},human,now);t.id=old.id;t.synthetic=!!old.synthetic;t.legacy=structuredClone(old);t.blocker=old.blocker||null;s.events.pop();event(s,human,'imported','Imported task. Fresh approvals required.',now,t,{synthetic:t.synthetic});}for(const old of legacy?.state?.tasks||[])entity(s,'tasks',old.id).dependencies=(old.dependencies||[]).filter(id=>entity(s,'tasks',id));for(const old of legacy?.state?.messages||[])s.messages.push({...old,id:`legacy:${old.id}`,imported:true,room:old.channel,recipients:[],receipts:[]});return s;}
export function controlPrincipal(s,identity){if(identity?.kind==='luna')return {actor:'luna',role:'luna',subject:identity.subject,agent:true};if(identity?.kind==='agent'&&CONTROL_AGENTS[identity.actor])return {actor:identity.actor,role:'agent',subject:identity.subject,agent:true};check(identity?.subject===s.meta.ownerId,'FORBIDDEN','Only the owner or an authenticated agent may access Relay.',403);return {actor:'human',role:'human',subject:identity.subject,agent:false};}
export function messageRecipients(s,m){if(m.actor==='human'&&m.room?.startsWith('task:')){const task=entity(s,'tasks',m.room.slice(5));if(task?.team)return task.team.owner?[task.team.owner]:TEAM_AGENTS;}if(m.actor==='human'&&m.kind!=='site_edit_request'&&['admin','general'].includes(m.room))return ['luna'];return m.actor==='human'&&m.projectId?(entity(s,'projects',m.projectId)?.owner?[entity(s,'projects',m.projectId).owner]:[]):m.recipients||[];}
export function messageRoom(s,m){return m.projectId&&m.room?.startsWith('direct:')&&entity(s,'projects',m.projectId)?.owner?`direct:${entity(s,'projects',m.projectId).owner}`:m.room;}
